function loadResearchHeic(){if(window.heic2any)return Promise.resolve(window.heic2any);if(researchHeicLoader)return researchHeicLoader;researchHeicLoader=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='vendor/heic2any/heic2any-0.0.4.min.js';script.onload=()=>typeof window.heic2any==='function'?resolve(window.heic2any):reject(Error('사진 변환 도구를 불러오지 못했어요.'));script.onerror=()=>{script.remove();reject(Error('사진 변환 도구를 불러오지 못했어요.'))};document.head.append(script)}).catch(error=>{researchHeicLoader=null;throw error});return researchHeicLoader}
